import csv, sys
from decimal import Decimal as D
from collections import defaultdict, Counter
s = sys.argv[1]
def rd(n): return list(csv.DictReader(open(f"{s}/{n}.csv", encoding="utf-8", newline=""), delimiter=";"))
r = rd("rastro"); tot = defaultdict(D)
for x in r: tot[x["id_saida"]] += D(x["valor"])
print("rastro linhas", len(r), "ids", len(tot), "soma", sum(tot.values()))
print(Counter(x["arquivo_origem"] for x in r))
cols = {"comissoes_por_lojista": "comissao_brl", "divergencias_taxa": "diferenca_brl", "notas_a_emitir": "valor_brl", "lancamentos_classificados": "valor", "pendencias": "valor_brl"}
ids = set()
for n, c in cols.items():
    rows = rd(n); bad = [x["id_saida"] for x in rows if tot.get(x["id_saida"]) != D(x[c])]
    ids |= {x["id_saida"] for x in rows}
    by = defaultdict(D)
    for x in rows: by[x.get("linha_negocio") or x.get("banco") or x.get("tipo")] += D(x[c])
    print(n, len(rows), sum(D(x[c]) for x in rows), dict(by), "naofecham", len(bad))
print("ids rastro sem saida", set(tot) - ids)
for x in rd("pendencias"): print(" PEN", x["id_saida"], x["tipo"], x["valor_brl"], "|", x["motivo"][:220], "|", x["quem_decide"])
for x in rd("comissoes_por_lojista"): print(" COM", x["linha_negocio"], x["lojista"][:30], x["comissao_brl"])
dv = rd("divergencias_taxa"); print(Counter((x["cnpj"], x["taxa_contratada_pct"], x["taxa_aplicada_pct"]) for x in dv))
print(Counter((x["conta_codigo"], x["banco"]) for x in rd("lancamentos_classificados")))

